from pathlib import Path
import base64, io, tarfile

RELEASE_ID = "jarvis-maintenance-voice-r1"

PAYLOAD = """"""

root = Path(".").resolve()
raw = base64.b64decode(PAYLOAD)
with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
    tf.extractall(root)

# Release validation: never deploy a stale payload silently.
dashboard = (root / "app" / "jarvis_dashboard.py").read_text(encoding="utf-8")
main_py = (root / "app" / "main.py").read_text(encoding="utf-8")
required = {
    "Maintenance tab": "Maintenance",
    "Marin voice": "Marin · natural",
    "Voice preview": "previewVoice()",
    "TTS endpoint": "/jarvis/tts",
    "Self-maintenance endpoint": "/maintenance/status",
}
combined = dashboard + "\n" + main_py
missing = [name for name, marker in required.items() if marker not in combined]
if missing:
    raise SystemExit(f"Jarvis release validation failed; missing: {', '.join(missing)}")
print(f"Jarvis application payload restored and validated: {RELEASE_ID}")
